// Player CSS
const PCSS = `
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
:root { --orange: #f05a28; --ink: #1C2433; --canvas: #FAF7F2; --line: #E4DFD6; --stone: #6E6A63; --gray-200: #e8e8e8; --gray-400: #999; --gray-600: #555; --mist: #F0ECE4; }
body { font-family: Arial, sans-serif; background: #fff; color: var(--ink); font-size: 12.5px; }
.page { width: 210mm; min-height: 297mm; padding: 12mm 14mm 10mm; background: var(--canvas); display: flex; flex-direction: column; gap: 9px; page-break-after: always; break-after: page; }
.page-header { display: flex; justify-content: space-between; align-items: flex-start; border-bottom: 2px solid var(--orange); padding-bottom: 9px; }
.page-header-left h2 { font-size: 1.3rem; font-weight: 900; color: var(--ink); margin-top: 4px; }
.month-label { font-size: 0.66rem; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--orange); }
.page-header-right { display: flex; flex-direction: column; align-items: flex-end; gap: 5px; }
.page-type-badge { font-size: 0.62rem; font-weight: 700; padding: 3px 8px; border-radius: 4px; letter-spacing: .08em; text-transform: uppercase; }
.badge-player { background: rgba(240,90,40,.12); color: var(--orange); border: 1px solid rgba(240,90,40,.3); }
.badge-coach { background: rgba(28,36,51,.12); color: var(--ink); border: 1px solid rgba(28,36,51,.3); }
.logo-small { font-weight: 900; font-size: 0.72rem; color: var(--stone); letter-spacing: .06em; }
.logo-small span { color: var(--orange); }
.goal-box { background: #fff; border: 1px solid var(--line); border-radius: 8px; padding: 9px 12px; }
.goal-label { font-size: 0.63rem; font-weight: 700; text-transform: uppercase; letter-spacing: .1em; color: var(--orange); margin-bottom: 5px; }
.goal-box ul { list-style: none; display: flex; flex-direction: column; gap: 3px; }
.goal-box li { font-size: 0.8rem; color: var(--gray-600); padding-left: 14px; position: relative; }
.goal-box li::before { content: '→'; position: absolute; left: 0; color: var(--orange); font-weight: 700; }
.intro-box { background: var(--mist); border-radius: 6px; padding: 8px 11px; font-size: 0.8rem; color: var(--gray-600); font-style: italic; }
.section-title { font-size: 0.63rem; font-weight: 700; text-transform: uppercase; letter-spacing: .1em; color: var(--stone); border-bottom: 1px solid var(--line); padding-bottom: 3px; }
.exercise-block { background: #fff; border: 1px solid var(--line); border-radius: 8px; padding: 9px 12px; }
.exercise-title { display: flex; align-items: center; gap: 8px; font-weight: 700; font-size: 0.86rem; margin-bottom: 5px; }
.exercise-number { background: var(--orange); color: #fff; width: 19px; height: 19px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 0.68rem; font-weight: 800; flex-shrink: 0; }
.exercise-instruction { font-size: 0.78rem; color: var(--gray-600); margin-bottom: 7px; }
.write-line { border-bottom: 1.5px solid var(--gray-200); height: 20px; width: 100%; }
.write-lines { display: flex; flex-direction: column; gap: 5px; }
.write-box { border: 1px solid var(--gray-200); border-radius: 4px; min-height: 48px; background: #fff; }
.write-box-lg { min-height: 72px; }
.two-col { display: grid; grid-template-columns: 1fr 1fr; gap: 9px; }
.quote-block { background: var(--ink); color: #fff; border-radius: 8px; padding: 11px 15px; margin-top: auto; }
.quote-block p { font-size: 0.8rem; font-style: italic; line-height: 1.5; margin-bottom: 5px; }
.quote-block cite { font-size: 0.66rem; color: rgba(255,255,255,.6); font-style: normal; }
.page-footer { display: flex; justify-content: space-between; font-size: 0.62rem; color: var(--stone); border-top: 1px solid var(--line); padding-top: 5px; margin-top: auto; }
.science-box { background: var(--ink); color: #fff; border-radius: 8px; padding: 9px 12px; font-size: 0.76rem; line-height: 1.44; }
.science-box strong { display: block; font-size: 0.68rem; letter-spacing: .06em; text-transform: uppercase; color: var(--orange); margin-bottom: 4px; }
.evidence-tier { display: inline-block; font-size: 0.59rem; font-weight: 700; padding: 1px 5px; border-radius: 3px; margin-right: 4px; vertical-align: middle; }
.tier-1 { background: #27ae60; color: #fff; }
.tier-2 { background: #2980b9; color: #fff; }
.tier-3 { background: #7f8c8d; color: #fff; }
.coach-section { display: flex; flex-direction: column; gap: 5px; }
.coach-section h3 { font-size: 0.7rem; font-weight: 700; text-transform: uppercase; letter-spacing: .08em; color: var(--orange); border-bottom: 1px solid var(--line); padding-bottom: 3px; }
.coach-step { display: flex; gap: 8px; align-items: flex-start; }
.step-num { background: var(--orange); color: #fff; width: 19px; height: 19px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 0.68rem; font-weight: 800; flex-shrink: 0; margin-top: 1px; }
.coach-step p { font-size: 0.77rem; color: var(--gray-600); line-height: 1.43; }
.tip-box { background: rgba(240,90,40,.07); border-left: 3px solid var(--orange); border-radius: 0 5px 5px 0; padding: 6px 9px; font-size: 0.76rem; color: var(--gray-600); line-height: 1.38; }
.warning-box { background: rgba(241,196,15,.1); border-left: 3px solid #f1c40f; border-radius: 0 5px 5px 0; padding: 6px 9px; font-size: 0.76rem; color: var(--gray-600); line-height: 1.38; }
.checklist { list-style: none; display: flex; flex-direction: column; gap: 3px; }
.checklist li { display: flex; align-items: center; gap: 7px; font-size: 0.76rem; color: var(--gray-600); }
.checkbox { width: 13px; height: 13px; border: 1.5px solid var(--gray-400); border-radius: 3px; flex-shrink: 0; }
.coach-page { background: #F5F3EF; }
@media print { body { -webkit-print-color-adjust: exact; print-color-adjust: exact; } }
`;

