const PLAYER_NL = [
  { m:1, title:'Zelfkennis & Identiteit', goalLabel:'Doelstelling Maand 1', goals:['Je kan drie kernwaarden benoemen die jou als persoon en ploegmaat definiëren','Je herkent wat je energie geeft en wat energie kost in een teamsetting','Je begrijpt het verschil tussen hoe jij jezelf ziet en hoe anderen jou ervaren'], intro:'Wie ben jij als speler en als persoon? Dit werkblad helpt je om je eigen krachten, waarden en motivatie beter te begrijpen. Neem de tijd en wees eerlijk.', badge:'Speler', monthLabel:'Maand 1 — Spelerswerkblad',
    exercises:`<div class="section-title">Oefening 1 — Mijn Drie Woorden</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">1</div>Mijn Drie Woorden</div><p class="exercise-instruction">Kies drie woorden die jou het best beschrijven als ploegmaat. Schrijf ze hieronder. Vraag daarna drie teamgenoten om ook drie woorden over jou op te schrijven en vergelijk de resultaten.</p><div class="write-lines"><div style="font-size:0.76rem;color:var(--gray-400);margin-bottom:3px">Mijn drie woorden:</div><div class="write-line"></div><div style="font-size:0.76rem;color:var(--gray-400);margin:7px 0 3px">Woorden van teamgenoot 1:</div><div class="write-line"></div><div style="font-size:0.76rem;color:var(--gray-400);margin:7px 0 3px">Woorden van teamgenoot 2:</div><div class="write-line"></div><div style="font-size:0.76rem;color:var(--gray-400);margin:7px 0 3px">Wat valt je op als je de lijsten vergelijkt?</div><div class="write-line"></div><div class="write-line"></div></div></div><div class="section-title">Oefening 2 — Energiegever vs Energieslurper</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">2</div>Energiegever vs Energieslurper</div><p class="exercise-instruction">Schrijf drie dingen op die je energie geven tijdens training of wedstrijd, en drie dingen die je energie kosten.</p><div class="two-col"><div><div style="font-size:0.73rem;font-weight:700;color:var(--orange);margin-bottom:5px">ENERGIEGEVERS ▶</div><div class="write-line"></div><div class="write-line" style="margin-top:7px"></div><div class="write-line" style="margin-top:7px"></div></div><div><div style="font-size:0.73rem;font-weight:700;color:#999;margin-bottom:5px">ENERGIESLURPERS ▼</div><div class="write-line"></div><div class="write-line" style="margin-top:7px"></div><div class="write-line" style="margin-top:7px"></div></div></div></div><div class="section-title">Oefening 3 — Persoonlijk Waardenkompas</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">3</div>Persoonlijk Waardenkompas</div><p class="exercise-instruction">Rangschik onderstaande waarden van 1 (meest belangrijk) tot 5 (minder belangrijk) voor jou als speler en als persoon.</p><div style="display:grid;grid-template-columns:1fr 1fr;gap:7px;margin-top:9px"><div style="display:flex;align-items:center;gap:7px;font-size:0.8rem"><div class="write-line" style="width:28px;height:20px"></div> Loyaliteit</div><div style="display:flex;align-items:center;gap:7px;font-size:0.8rem"><div class="write-line" style="width:28px;height:20px"></div> Eerlijkheid</div><div style="display:flex;align-items:center;gap:7px;font-size:0.8rem"><div class="write-line" style="width:28px;height:20px"></div> Moed</div><div style="display:flex;align-items:center;gap:7px;font-size:0.8rem"><div class="write-line" style="width:28px;height:20px"></div> Doorzetting</div><div style="display:flex;align-items:center;gap:7px;font-size:0.8rem"><div class="write-line" style="width:28px;height:20px"></div> Respect</div><div style="display:flex;align-items:center;gap:7px;font-size:0.8rem"><div class="write-line" style="width:28px;height:20px"></div> Teamgeest</div></div><div style="font-size:0.76rem;color:var(--gray-400);margin-top:11px">Welke waarde leef jij het minst na? Wat wil je veranderen?</div><div class="write-box"></div></div>`,
    quote:'"The most important thing is to try and inspire people so that they can be great in whatever they want to do."', cite:'Kobe Bryant — 5x NBA Champion, Los Angeles Lakers', footer:'Maand 1: Zelfkennis & Identiteit', email:'info@characterfirst.be' },
  { m:2, title:'Druk & Stress', goalLabel:'Doelstelling Maand 2', goals:['Je herkent de fysieke en mentale signalen van stress bij jezelf','Je beheerst minstens één ademhalingstechniek om activatie te reguleren','Je kan het verschil benoemen tussen probleemgerichte en emotiegerichte coping'], intro:'Druk voelen is normaal. Elk topsporter voelt het. Wat het verschil maakt is hoe je ermee omgaat. Dit werkblad helpt je te ontdekken hoe jouw lichaam en geest reageren op stress.', badge:'Speler', monthLabel:'Maand 2 — Spelerswerkblad',
    exercises:`<div class="section-title">Oefening 1 — Box Breathing</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">1</div>Box Breathing Logboek</div><p class="exercise-instruction">Oefen Box Breathing minstens 3x deze maand voor een training of wedstrijd. Vul in na elke keer: hoe voelde je je voor en na?</p><div style="display:grid;grid-template-columns:2fr 1fr 1fr;gap:7px;margin-top:7px"><div style="font-size:0.7rem;font-weight:700;color:var(--gray-400)">DATUM / SITUATIE</div><div style="font-size:0.7rem;font-weight:700;color:var(--gray-400)">VOOR (1-10)</div><div style="font-size:0.7rem;font-weight:700;color:var(--gray-400)">NA (1-10)</div><div class="write-line"></div><div class="write-line"></div><div class="write-line"></div><div class="write-line"></div><div class="write-line"></div><div class="write-line"></div><div class="write-line"></div><div class="write-line"></div><div class="write-line"></div></div></div><div class="section-title">Oefening 2 — Stressdagboek</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">2</div>Stressdagboek</div><p class="exercise-instruction">Schrijf na je volgende wedstrijd drie dingen op: wat voelde je, wat dacht je, en wat deed je?</p><div style="font-size:0.76rem;color:var(--gray-400);margin-bottom:3px">Wat voelde ik? (fysiek en emotioneel)</div><div class="write-box"></div><div style="font-size:0.76rem;color:var(--gray-400);margin:9px 0 3px">Wat dacht ik?</div><div class="write-box"></div><div style="font-size:0.76rem;color:var(--gray-400);margin:9px 0 3px">Wat deed ik? (hoe reageerde ik op de druk?)</div><div class="write-box"></div></div><div class="section-title">Oefening 3 — Worst Case Best Case</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">3</div>Worst Case Best Case</div><p class="exercise-instruction">Denk aan een aankomende situatie die je zenuwachtig maakt. Schrijf de drie scenario's.</p><div class="two-col"><div><div style="font-size:0.73rem;font-weight:700;color:#c0392b;margin-bottom:4px">Worst Case</div><div class="write-box"></div></div><div><div style="font-size:0.73rem;font-weight:700;color:#27ae60;margin-bottom:4px">Best Case</div><div class="write-box"></div></div></div><div style="font-size:0.73rem;font-weight:700;color:var(--orange);margin:9px 0 4px">Meest Waarschijnlijk</div><div class="write-box"></div></div>`,
    quote:'"Pressure is a privilege — it only comes to those who earn it."', cite:'Billie Jean King — 39x Grand Slam Champion', footer:'Maand 2: Druk & Stress', email:'info@characterfirst.be' },
  { m:3, title:'Mijn Rol in het Team', goalLabel:'Doelstelling Maand 3', goals:['Je kan jouw huidige rol(len) in het team benoemen met concrete voorbeelden','Je begrijpt waarom rolhelderheid bijdraagt aan teamcohesie en persoonlijke motivatie','Je formuleert één concrete bijdrage die jij wil versterken de komende maanden'], intro:'Je hebt niet één rol in een team. Je hebt er meerdere, en ze veranderen. Dit werkblad helpt je ontdekken welke rollen jij vervult en welke je wil ontwikkelen.', badge:'Speler', monthLabel:'Maand 3 — Spelerswerkblad',
    exercises:`<div class="section-title">Oefening 1 — Rolcompass</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">1</div>Rolcompass</div><p class="exercise-instruction">Geef jezelf een score van 0 tot 10 voor elk van de vier rollen hieronder. Kleur de balken in.</p><div style="display:flex;flex-direction:column;gap:11px;margin-top:9px"><div><div style="display:flex;justify-content:space-between;font-size:0.78rem;margin-bottom:3px"><strong>Leider</strong><span style="color:var(--gray-400);font-size:0.73rem">Geeft richting, spreekt de groep toe</span></div><div style="height:13px;background:var(--gray-200);border-radius:4px;position:relative"><div style="position:absolute;right:4px;top:50%;transform:translateY(-50%);font-size:0.63rem;color:var(--gray-400)">Score: ___/10</div></div></div><div><div style="display:flex;justify-content:space-between;font-size:0.78rem;margin-bottom:3px"><strong>Motor</strong><span style="color:var(--gray-400);font-size:0.73rem">Geeft energie, trekt het team mee</span></div><div style="height:13px;background:var(--gray-200);border-radius:4px;position:relative"><div style="position:absolute;right:4px;top:50%;transform:translateY(-50%);font-size:0.63rem;color:var(--gray-400)">Score: ___/10</div></div></div><div><div style="display:flex;justify-content:space-between;font-size:0.78rem;margin-bottom:3px"><strong>Denker</strong><span style="color:var(--gray-400);font-size:0.73rem">Analyseert, stelt vragen, zoekt oplossingen</span></div><div style="height:13px;background:var(--gray-200);border-radius:4px;position:relative"><div style="position:absolute;right:4px;top:50%;transform:translateY(-50%);font-size:0.63rem;color:var(--gray-400)">Score: ___/10</div></div></div><div><div style="display:flex;justify-content:space-between;font-size:0.78rem;margin-bottom:3px"><strong>Stabiele Kracht</strong><span style="color:var(--gray-400);font-size:0.73rem">Betrouwbaar, consistent, steun voor anderen</span></div><div style="height:13px;background:var(--gray-200);border-radius:4px;position:relative"><div style="position:absolute;right:4px;top:50%;transform:translateY(-50%);font-size:0.63rem;color:var(--gray-400)">Score: ___/10</div></div></div></div></div><div class="section-title">Oefening 2 — Mijn Bijdrage</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">2</div>Mijn Top 3 Bijdragen deze maand</div><p class="exercise-instruction">Geen statistieken. Geen punten. Schrijf drie dingen op die jij hebt bijgedragen aan het team op het vlak van gedrag, houding of karakter.</p><div class="write-lines"><div style="display:flex;align-items:center;gap:7px;margin-bottom:3px"><div class="exercise-number" style="flex-shrink:0">1</div><div class="write-line" style="flex:1"></div></div><div style="display:flex;align-items:center;gap:7px;margin-bottom:3px"><div class="exercise-number" style="flex-shrink:0">2</div><div class="write-line" style="flex:1"></div></div><div style="display:flex;align-items:center;gap:7px"><div class="exercise-number" style="flex-shrink:0">3</div><div class="write-line" style="flex:1"></div></div></div></div><div class="section-title">Oefening 3 — Rolcirkel Reflectie</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">3</div>Na de Rolcirkel Oefening</div><p class="exercise-instruction">Na de groepsoefening: wat heeft je verrast? Welke bijdrage van een teamgenoot had je nooit verwacht?</p><div class="write-box write-box-lg"></div></div>`,
    quote:'"The strength of the team is each individual member. The strength of each member is the team. I never tried to be the best player. I tried to be the player we needed."', cite:'Phil Jackson — 11x NBA Championship coach', footer:'Maand 3: Mijn Rol in het Team', email:'info@characterfirst.be' },
  { m:4, title:'Communicatie', goalLabel:'Doelstelling Maand 4', goals:['Je kan het Ik Boodschap model toepassen in een echte situatie uit je sportleven','Je geeft constructieve feedback aan een teamgenoot zonder beschuldiging of defensiviteit op te wekken','Je plant en voert minstens één moeilijk gesprek dat je al uitstelde'], intro:'Hoe je praat bepaalt hoe je samenwerkt. Je leert het verschil tussen reageren en echt communiceren, en hoe je feedback geeft zonder relaties te beschadigen.', badge:'Speler', monthLabel:'Maand 4 — Spelerswerkblad',
    exercises:`<div class="section-title">Oefening 1 — Ik Boodschap</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">1</div>De Ik Boodschap</div><p class="exercise-instruction">Het model: "Ik zie... Ik voel... Ik heb nodig... Ik vraag je om..." Schrijf een situatie uit je sportleven uit met dit model.</p><div style="display:flex;flex-direction:column;gap:7px;margin-top:9px"><div><div style="font-size:0.73rem;color:var(--orange);font-weight:700">IK ZIE...</div><div class="write-line"></div></div><div><div style="font-size:0.73rem;color:var(--orange);font-weight:700">IK VOEL...</div><div class="write-line"></div></div><div><div style="font-size:0.73rem;color:var(--orange);font-weight:700">IK HEB NODIG...</div><div class="write-line"></div></div><div><div style="font-size:0.73rem;color:var(--orange);font-weight:700">IK VRAAG JE OM...</div><div class="write-line"></div></div></div></div><div class="section-title">Oefening 2 — Moeilijk Gesprek</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">2</div>Het Gesprek dat ik Uitstel</div><p class="exercise-instruction">Schrijf een gesprek op dat je al lang wil hebben maar uitstelt. Met een coach, teamgenoot of ouder.</p><div style="font-size:0.76rem;color:var(--gray-400);margin-bottom:3px">Met wie is dit gesprek?</div><div class="write-line"></div><div style="font-size:0.76rem;color:var(--gray-400);margin:9px 0 3px">Waarom stel ik het uit?</div><div class="write-box"></div><div style="font-size:0.76rem;color:var(--gray-400);margin:9px 0 3px">Schrijf de eerste zin waarmee je het gesprek opent (gebruik de Ik Boodschap):</div><div class="write-box"></div><div style="font-size:0.76rem;color:var(--gray-400);margin:9px 0 3px">Wanneer ga ik dit gesprek plannen? (datum + plaats)</div><div class="write-line"></div></div><div class="section-title">Oefening 3 — Feedbackronde Reflectie</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">3</div>Na de Feedbackronde</div><p class="exercise-instruction">Wat was de beste feedback die je kreeg? Wat ga je er concreet mee doen?</p><div class="write-box write-box-lg"></div></div>`,
    quote:'"Communication is the most important skill any leader can possess."', cite:'Doc Rivers — NBA Head Coach', footer:'Maand 4: Communicatie', email:'info@characterfirst.be' },
  { m:5, title:'Team Eerst', goalLabel:'Doelstelling Maand 5', goals:['Je kan uitleggen wat psychologische veiligheid is en waarom het teamsprestaties beïnvloedt','Je draagt actief bij aan een veilig teamklimaat door hulp te vragen en anderen te erkennen','Je sluit mee een gezamenlijk team contract af dat het seizoen begeleidt'], intro:'De stap van "ik" naar "wij" is de moeilijkste in de sport. Vandaag onderzoek je wat het echt betekent om het team voorop te stellen, ook als het je iets kost.', badge:'Speler', monthLabel:'Maand 5 — Spelerswerkblad',
    exercises:`<div class="section-title">Oefening 1 — Team Contract</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">1</div>Mijn Bijdrage aan het Team Contract</div><p class="exercise-instruction">Schrijf drie gedragsregels op die jij persoonlijk wil naleven dit seizoen, niet over winnen, maar over hoe je met je teamgenoten omgaat.</p><div class="write-lines" style="gap:9px"><div style="display:flex;align-items:center;gap:7px"><span style="font-size:0.73rem;font-weight:700;color:var(--orange);white-space:nowrap">Ik beloof om</span><div class="write-line" style="flex:1"></div></div><div style="display:flex;align-items:center;gap:7px"><span style="font-size:0.73rem;font-weight:700;color:var(--orange);white-space:nowrap">Ik beloof om</span><div class="write-line" style="flex:1"></div></div><div style="display:flex;align-items:center;gap:7px"><span style="font-size:0.73rem;font-weight:700;color:var(--orange);white-space:nowrap">Ik beloof om</span><div class="write-line" style="flex:1"></div></div></div><div style="margin-top:12px;display:flex;gap:18px"><div style="flex:1"><div style="font-size:0.73rem;color:var(--gray-400);margin-bottom:5px">Handtekening</div><div class="write-line"></div></div><div style="flex:1"><div style="font-size:0.73rem;color:var(--gray-400);margin-bottom:5px">Datum</div><div class="write-line"></div></div></div></div><div class="section-title">Oefening 2 — Onzichtbare Bijdrage</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">2</div>Onzichtbare Bijdrage</div><p class="exercise-instruction">Schrijf één teamgenoot op die iets deed tijdens de laatste wedstrijd of training wat niemand opmerkte maar essentieel was voor het team. Wat deed deze persoon?</p><div style="font-size:0.76rem;color:var(--gray-400);margin-bottom:3px">Naam teamgenoot:</div><div class="write-line"></div><div style="font-size:0.76rem;color:var(--gray-400);margin:9px 0 3px">Wat deed hij of zij?</div><div class="write-box write-box-lg"></div></div><div class="section-title">Oefening 3 — Hulp Vragen</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">3</div>Hulp Logboek</div><p class="exercise-instruction">Vraag deze maand minstens 3x actief om hulp aan een teamgenoot tijdens training. Schrijf op wat je vroeg en wat het opleverde.</p><div style="display:grid;grid-template-columns:2fr 2fr 1fr;gap:7px;margin-top:7px"><div style="font-size:0.7rem;font-weight:700;color:var(--gray-400)">WAT VROEG IK?</div><div style="font-size:0.7rem;font-weight:700;color:var(--gray-400)">WAT LEVERDE HET OP?</div><div style="font-size:0.7rem;font-weight:700;color:var(--gray-400)">DATUM</div><div class="write-line"></div><div class="write-line"></div><div class="write-line"></div><div class="write-line"></div><div class="write-line"></div><div class="write-line"></div><div class="write-line"></div><div class="write-line"></div><div class="write-line"></div></div></div>`,
    quote:'"Talent wins games, but teamwork and intelligence win championships."', cite:'Michael Jordan — 6x NBA Champion', footer:'Maand 5: Team Eerst', email:'info@characterfirst.be' },
  { m:6, title:'Veerkracht & Groeimindset', goalLabel:'Doelstelling Maand 6', goals:['Je onderscheidt een fixed mindset reactie van een groeimindset reactie bij jezelf','Je herschrijft minstens één negatieve zelfgedachte naar een leergerichte formulering','Je benoemt drie concrete manieren waarop je gegroeid bent dit seizoen ten opzichte van jezelf'], intro:'Hoe je omgaat met tegenslagen en fouten bepaalt hoe ver je komt in de sport en in het leven. Een groeimindset is niet aangeboren. Je kan het trainen.', badge:'Speler', monthLabel:'Maand 6 — Spelerswerkblad',
    exercises:`<div class="section-title">Oefening 1 — Herschrijf de Fout</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">1</div>Herschrijf de Fout</div><p class="exercise-instruction">Schrijf een recente fout of tegenslag op. Daarna herschrijf je elke gedachte met "ik kan het niet" naar "ik kan het nog niet" en voeg toe wat je ervan leert.</p><div style="font-size:0.76rem;color:var(--gray-400);margin-bottom:3px">De situatie of fout:</div><div class="write-box"></div><div class="two-col" style="margin-top:9px"><div><div style="font-size:0.7rem;font-weight:700;color:#c0392b;margin-bottom:4px">WAT IK DACHT (fixed)</div><div class="write-box"></div></div><div><div style="font-size:0.7rem;font-weight:700;color:#27ae60;margin-bottom:4px">HOE IK HET HERSCHRIJF (growth)</div><div class="write-box"></div></div></div></div><div class="section-title">Oefening 2 — Progressielijst</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">2</div>3 Dingen die ik Beter Kan dan Vorige Maand</div><p class="exercise-instruction">Geen vergelijking met anderen. Enkel met jezelf. Schrijf drie concrete dingen op.</p><div class="write-lines" style="gap:9px"><div style="display:flex;align-items:center;gap:7px"><div class="exercise-number" style="flex-shrink:0">1</div><div class="write-line" style="flex:1"></div></div><div style="display:flex;align-items:center;gap:7px"><div class="exercise-number" style="flex-shrink:0">2</div><div class="write-line" style="flex:1"></div></div><div style="display:flex;align-items:center;gap:7px"><div class="exercise-number" style="flex-shrink:0">3</div><div class="write-line" style="flex:1"></div></div></div></div><div class="section-title">Oefening 3 — Mijn Moeilijkste Moment</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">3</div>Moeilijkste Moment van dit Seizoen</div><p class="exercise-instruction">Beschrijf het moeilijkste moment van dit seizoen. Wat deed je? Wat leerde je? Hoe ben je sterker geworden?</p><div style="font-size:0.76rem;color:var(--gray-400);margin-bottom:3px">Wat was het moment?</div><div class="write-box"></div><div style="font-size:0.76rem;color:var(--gray-400);margin:7px 0 3px">Wat leerde ik ervan?</div><div class="write-box"></div></div>`,
    quote:'"I have failed over and over again in my life. And that is why I succeed."', cite:'Michael Jordan — 6x NBA Champion', footer:'Maand 6: Veerkracht & Groeimindset', email:'info@characterfirst.be' },
  { m:7, title:'Leiderschap van Binnenuit', goalLabel:'Doelstelling Maand 7', goals:['Je herkent informeel leiderschap bij jezelf en anderen zonder te kijken naar officiële rollen','Je neemt minstens éénmaal per week bewust een leidersmoment in training of wedstrijd','Je investeert actief in de ontwikkeling van een jongere of nieuwe teamgenoot'], intro:'Leiderschap gaat niet over de aanvoerdersband. Elke speler kan op elk moment leiden door gedrag, houding en woorden. Jij ook.', badge:'Speler', monthLabel:'Maand 7 — Spelerswerkblad',
    exercises:`<div class="section-title">Oefening 1 — Wie Volg ik?</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">1</div>Informele Leiders in ons Team</div><p class="exercise-instruction">Schrijf twee teamgenoten op die jij volgt, niet omdat ze aanvoerder zijn, maar omdat ze iets uitstralen. Wat doen ze concreet dat invloed heeft?</p><div style="margin-bottom:11px"><div style="font-size:0.73rem;color:var(--gray-400);margin-bottom:3px">Persoon 1 naam:</div><div class="write-line"></div><div style="font-size:0.73rem;color:var(--gray-400);margin:5px 0 3px">Wat maakt hem of haar invloedrijk?</div><div class="write-box"></div></div><div><div style="font-size:0.73rem;color:var(--gray-400);margin-bottom:3px">Persoon 2 naam:</div><div class="write-line"></div><div style="font-size:0.73rem;color:var(--gray-400);margin:5px 0 3px">Wat maakt hem of haar invloedrijk?</div><div class="write-box"></div></div></div><div class="section-title">Oefening 2 — Mentor een Jongere Speler</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">2</div>Mijn Mentormoment</div><p class="exercise-instruction">Kies een jongere speler of nieuwe teamgenoot. Besteed deze maand minstens eenmaal 5 minuten aan hem of haar. Schrijf op wat je wilde meegeven en hoe het ging.</p><div style="font-size:0.76rem;color:var(--gray-400);margin-bottom:3px">Met wie?</div><div class="write-line"></div><div style="font-size:0.76rem;color:var(--gray-400);margin:7px 0 3px">Wat wilde ik meegeven?</div><div class="write-box"></div><div style="font-size:0.76rem;color:var(--gray-400);margin:7px 0 3px">Hoe reageerde die persoon?</div><div class="write-box"></div></div><div class="section-title">Oefening 3 — De Eerste Stem</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">3</div>Mijn Leidersmomenten</div><p class="exercise-instruction">Schrijf na elke training of wedstrijd op: wanneer was jij de eerste stem? Wanneer nam je een leidersmoment?</p><div class="write-box write-box-lg"></div></div>`,
    quote:'"I like pressure. It\'s a privilege to be in pressure situations."', cite:'LeBron James — 4x NBA Champion, Los Angeles Lakers', footer:'Maand 7: Leiderschap van Binnenuit', email:'info@characterfirst.be' },
  { m:8, title:'Nalatenschap & Volgende Stap', goalLabel:'Doelstelling Maand 8', goals:['Je reflecteert op je groei als persoon en als ploegmaat over het volledige seizoen','Je formuleert drie concrete, gedragsgerichte intenties voor volgend seizoen','Je sluit het seizoen af met een bewust gevoel van zingeving en bijdrage aan het team'], intro:'Dit is het laatste werkblad van het seizoen. Je sluit af met reflectie op wie je bent geworden, wat je hebt bijgedragen en welke stap je wil zetten.', badge:'Speler', monthLabel:'Maand 8 — Spelerswerkblad',
    exercises:`<div class="section-title">Oefening 1 — Mijn Bijdrage dit Seizoen</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">1</div>5 Momenten van Karakter</div><p class="exercise-instruction">Schrijf vijf concrete momenten op dit seizoen waarop jij iets hebt bijgedragen dat het team sterker maakte. Geen statistieken, enkel gedrag en karakter.</p><div class="write-lines" style="gap:7px"><div style="display:flex;align-items:flex-start;gap:7px"><div class="exercise-number" style="flex-shrink:0;margin-top:2px">1</div><div class="write-box" style="flex:1;height:32px"></div></div><div style="display:flex;align-items:flex-start;gap:7px"><div class="exercise-number" style="flex-shrink:0;margin-top:2px">2</div><div class="write-box" style="flex:1;height:32px"></div></div><div style="display:flex;align-items:flex-start;gap:7px"><div class="exercise-number" style="flex-shrink:0;margin-top:2px">3</div><div class="write-box" style="flex:1;height:32px"></div></div><div style="display:flex;align-items:flex-start;gap:7px"><div class="exercise-number" style="flex-shrink:0;margin-top:2px">4</div><div class="write-box" style="flex:1;height:32px"></div></div><div style="display:flex;align-items:flex-start;gap:7px"><div class="exercise-number" style="flex-shrink:0;margin-top:2px">5</div><div class="write-box" style="flex:1;height:32px"></div></div></div></div><div class="section-title">Oefening 2 — Drie Intenties voor Volgend Seizoen</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">2</div>Mijn Intenties</div><p class="exercise-instruction">Schrijf drie concrete intenties voor volgend seizoen. Eén voor jezelf, één voor het team, één voor je coach. Maak ze specifiek in gedrag.</p><div style="display:flex;flex-direction:column;gap:9px;margin-top:7px"><div><div style="font-size:0.73rem;font-weight:700;color:var(--orange);margin-bottom:4px">VOOR MEZELF</div><div class="write-box"></div></div><div><div style="font-size:0.73rem;font-weight:700;color:var(--orange);margin-bottom:4px">VOOR HET TEAM</div><div class="write-box"></div></div><div><div style="font-size:0.73rem;font-weight:700;color:var(--orange);margin-bottom:4px">VOOR MIJN COACH</div><div class="write-box"></div></div></div></div><div class="section-title">Brief aan Mezelf</div><div class="exercise-block" style="border:2px dashed var(--orange)"><div class="exercise-title"><div class="exercise-number">3</div>Brief aan Mijn Toekomstige Zelf</div><p class="exercise-instruction">Schrijf een brief aan jezelf van volgend seizoen. Wat hoop je te hebben geleerd? Welk type ploegmaat wil je zijn? Deze brief wordt bewaard en geopend bij de start van volgend seizoen.</p><div class="write-box write-box-lg"></div><div style="font-size:0.76rem;color:var(--gray-400);margin-top:7px">Datum: _________________ Handtekening: _________________</div></div>`,
    quote:'"The strength of the team is each individual member. The strength of each member is the team."', cite:'Phil Jackson — 11x NBA Championship coach', footer:'Maand 8: Nalatenschap & Volgende Stap', email:'info@characterfirst.be' },
];

// EN player data
const PLAYER_EN = [
  { m:1, title:'Self-Knowledge & Identity', goalLabel:'Goals Month 1', goals:['You can name three core values that define you as a person and teammate','You recognize what gives you energy and what costs energy in a team setting','You understand the difference between how you see yourself and how others see you'], intro:'Who are you as a player and as a person? This worksheet helps you better understand your own strengths, values, and motivation. Take your time and be honest.', badge:'Player', monthLabel:'Month 1 — Player Worksheet',
    exercises:`<div class="section-title">Exercise 1 — My Three Words</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">1</div>My Three Words</div><p class="exercise-instruction">Choose three words that best describe you as a teammate. Write them below. Then ask three teammates to write three words about you and compare the results.</p><div class="write-lines"><div style="font-size:0.76rem;color:var(--gray-400);margin-bottom:3px">My three words:</div><div class="write-line"></div><div style="font-size:0.76rem;color:var(--gray-400);margin:7px 0 3px">Words from teammate 1:</div><div class="write-line"></div><div style="font-size:0.76rem;color:var(--gray-400);margin:7px 0 3px">Words from teammate 2:</div><div class="write-line"></div><div style="font-size:0.76rem;color:var(--gray-400);margin:7px 0 3px">What stands out when you compare the lists?</div><div class="write-line"></div><div class="write-line"></div></div></div><div class="section-title">Exercise 2 — Energy Givers vs Energy Drains</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">2</div>Energy Givers vs Energy Drains</div><p class="exercise-instruction">Write three things that give you energy during training or a match, and three things that cost you energy.</p><div class="two-col"><div><div style="font-size:0.73rem;font-weight:700;color:var(--orange);margin-bottom:5px">ENERGY GIVERS ▶</div><div class="write-line"></div><div class="write-line" style="margin-top:7px"></div><div class="write-line" style="margin-top:7px"></div></div><div><div style="font-size:0.73rem;font-weight:700;color:#999;margin-bottom:5px">ENERGY DRAINS ▼</div><div class="write-line"></div><div class="write-line" style="margin-top:7px"></div><div class="write-line" style="margin-top:7px"></div></div></div></div><div class="section-title">Exercise 3 — Personal Values Compass</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">3</div>Personal Values Compass</div><p class="exercise-instruction">Rank the values below from 1 (most important) to 5 (less important) for you as a player and person.</p><div style="display:grid;grid-template-columns:1fr 1fr;gap:7px;margin-top:9px"><div style="display:flex;align-items:center;gap:7px;font-size:0.8rem"><div class="write-line" style="width:28px;height:20px"></div> Loyalty</div><div style="display:flex;align-items:center;gap:7px;font-size:0.8rem"><div class="write-line" style="width:28px;height:20px"></div> Honesty</div><div style="display:flex;align-items:center;gap:7px;font-size:0.8rem"><div class="write-line" style="width:28px;height:20px"></div> Courage</div><div style="display:flex;align-items:center;gap:7px;font-size:0.8rem"><div class="write-line" style="width:28px;height:20px"></div> Persistence</div><div style="display:flex;align-items:center;gap:7px;font-size:0.8rem"><div class="write-line" style="width:28px;height:20px"></div> Respect</div><div style="display:flex;align-items:center;gap:7px;font-size:0.8rem"><div class="write-line" style="width:28px;height:20px"></div> Team Spirit</div></div><div style="font-size:0.76rem;color:var(--gray-400);margin-top:11px">Which value do you live by the least? What do you want to change?</div><div class="write-box"></div></div>`,
    quote:'"The most important thing is to try and inspire people so that they can be great in whatever they want to do."', cite:'Kobe Bryant — 5x NBA Champion, Los Angeles Lakers', footer:'Month 1: Self-Knowledge & Identity', email:'info@characterfirst.be' },
  { m:2, title:'Pressure & Stress', goalLabel:'Goals Month 2', goals:['You recognize the physical and mental signals of stress in yourself','You master at least one breathing technique to regulate activation','You can name the difference between problem-focused and emotion-focused coping'], intro:'Feeling pressure is normal. Every top athlete feels it. What makes the difference is how you deal with it. This worksheet helps you discover how your body and mind respond to stress.', badge:'Player', monthLabel:'Month 2 — Player Worksheet',
    exercises:`<div class="section-title">Exercise 1 — Box Breathing</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">1</div>Box Breathing Log</div><p class="exercise-instruction">Practice Box Breathing at least 3 times this month before training or a match. Fill in after each time: how did you feel before and after?</p><div style="display:grid;grid-template-columns:2fr 1fr 1fr;gap:7px;margin-top:7px"><div style="font-size:0.7rem;font-weight:700;color:var(--gray-400)">DATE / SITUATION</div><div style="font-size:0.7rem;font-weight:700;color:var(--gray-400)">BEFORE (1-10)</div><div style="font-size:0.7rem;font-weight:700;color:var(--gray-400)">AFTER (1-10)</div><div class="write-line"></div><div class="write-line"></div><div class="write-line"></div><div class="write-line"></div><div class="write-line"></div><div class="write-line"></div><div class="write-line"></div><div class="write-line"></div><div class="write-line"></div></div></div><div class="section-title">Exercise 2 — Stress Diary</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">2</div>Stress Diary</div><p class="exercise-instruction">Write three things after your next match: what did you feel, what did you think, and what did you do?</p><div style="font-size:0.76rem;color:var(--gray-400);margin-bottom:3px">What did I feel? (physical and emotional)</div><div class="write-box"></div><div style="font-size:0.76rem;color:var(--gray-400);margin:9px 0 3px">What did I think?</div><div class="write-box"></div><div style="font-size:0.76rem;color:var(--gray-400);margin:9px 0 3px">What did I do? (how did I respond to the pressure?)</div><div class="write-box"></div></div><div class="section-title">Exercise 3 — Worst Case Best Case</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">3</div>Worst Case Best Case</div><p class="exercise-instruction">Think of an upcoming situation that makes you nervous. Write the three scenarios.</p><div class="two-col"><div><div style="font-size:0.73rem;font-weight:700;color:#c0392b;margin-bottom:4px">Worst Case</div><div class="write-box"></div></div><div><div style="font-size:0.73rem;font-weight:700;color:#27ae60;margin-bottom:4px">Best Case</div><div class="write-box"></div></div></div><div style="font-size:0.73rem;font-weight:700;color:var(--orange);margin:9px 0 4px">Most Likely</div><div class="write-box"></div></div>`,
    quote:'"Pressure is a privilege — it only comes to those who earn it."', cite:'Billie Jean King — 39x Grand Slam Champion', footer:'Month 2: Pressure & Stress', email:'info@characterfirst.be' },
  { m:3, title:'My Role in the Team', goalLabel:'Goals Month 3', goals:['You can name your current role(s) in the team with concrete examples','You understand why role clarity contributes to team cohesion and personal motivation','You formulate one concrete contribution you want to strengthen in the coming months'], intro:'You don\'t have one role in a team. You have several, and they change. This worksheet helps you discover which roles you fulfill and which you want to develop.', badge:'Player', monthLabel:'Month 3 — Player Worksheet',
    exercises:`<div class="section-title">Exercise 1 — Role Compass</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">1</div>Role Compass</div><p class="exercise-instruction">Give yourself a score from 0 to 10 for each of the four roles below. Color in the bars.</p><div style="display:flex;flex-direction:column;gap:11px;margin-top:9px"><div><div style="display:flex;justify-content:space-between;font-size:0.78rem;margin-bottom:3px"><strong>Leader</strong><span style="color:var(--gray-400);font-size:0.73rem">Gives direction, addresses the group</span></div><div style="height:13px;background:var(--gray-200);border-radius:4px;position:relative"><div style="position:absolute;right:4px;top:50%;transform:translateY(-50%);font-size:0.63rem;color:var(--gray-400)">Score: ___/10</div></div></div><div><div style="display:flex;justify-content:space-between;font-size:0.78rem;margin-bottom:3px"><strong>Engine</strong><span style="color:var(--gray-400);font-size:0.73rem">Gives energy, pulls the team along</span></div><div style="height:13px;background:var(--gray-200);border-radius:4px;position:relative"><div style="position:absolute;right:4px;top:50%;transform:translateY(-50%);font-size:0.63rem;color:var(--gray-400)">Score: ___/10</div></div></div><div><div style="display:flex;justify-content:space-between;font-size:0.78rem;margin-bottom:3px"><strong>Thinker</strong><span style="color:var(--gray-400);font-size:0.73rem">Analyzes, asks questions, finds solutions</span></div><div style="height:13px;background:var(--gray-200);border-radius:4px;position:relative"><div style="position:absolute;right:4px;top:50%;transform:translateY(-50%);font-size:0.63rem;color:var(--gray-400)">Score: ___/10</div></div></div><div><div style="display:flex;justify-content:space-between;font-size:0.78rem;margin-bottom:3px"><strong>Stable Force</strong><span style="color:var(--gray-400);font-size:0.73rem">Reliable, consistent, support for others</span></div><div style="height:13px;background:var(--gray-200);border-radius:4px;position:relative"><div style="position:absolute;right:4px;top:50%;transform:translateY(-50%);font-size:0.63rem;color:var(--gray-400)">Score: ___/10</div></div></div></div></div><div class="section-title">Exercise 2 — My Contribution</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">2</div>My Top 3 Contributions This Month</div><p class="exercise-instruction">No statistics. No points. Write three things you have contributed to the team in terms of behavior, attitude, or character.</p><div class="write-lines"><div style="display:flex;align-items:center;gap:7px;margin-bottom:3px"><div class="exercise-number" style="flex-shrink:0">1</div><div class="write-line" style="flex:1"></div></div><div style="display:flex;align-items:center;gap:7px;margin-bottom:3px"><div class="exercise-number" style="flex-shrink:0">2</div><div class="write-line" style="flex:1"></div></div><div style="display:flex;align-items:center;gap:7px"><div class="exercise-number" style="flex-shrink:0">3</div><div class="write-line" style="flex:1"></div></div></div></div><div class="section-title">Exercise 3 — Role Circle Reflection</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">3</div>After the Role Circle Exercise</div><p class="exercise-instruction">After the group exercise: what surprised you? Which contribution from a teammate did you never expect?</p><div class="write-box write-box-lg"></div></div>`,
    quote:'"The strength of the team is each individual member. The strength of each member is the team."', cite:'Phil Jackson — 11x NBA Championship coach', footer:'Month 3: My Role in the Team', email:'info@characterfirst.be' },
  { m:4, title:'Communication', goalLabel:'Goals Month 4', goals:['You can apply the I-Message model in a real situation from your sports life','You give constructive feedback to a teammate without triggering blame or defensiveness','You plan and have at least one difficult conversation you have been postponing'], intro:'How you speak determines how you work together. You learn the difference between reacting and truly communicating, and how to give feedback without damaging relationships.', badge:'Player', monthLabel:'Month 4 — Player Worksheet',
    exercises:`<div class="section-title">Exercise 1 — I-Message</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">1</div>The I-Message</div><p class="exercise-instruction">The model: "I see... I feel... I need... I ask you to..." Write a situation from your sports life using this model.</p><div style="display:flex;flex-direction:column;gap:7px;margin-top:9px"><div><div style="font-size:0.73rem;color:var(--orange);font-weight:700">I SEE...</div><div class="write-line"></div></div><div><div style="font-size:0.73rem;color:var(--orange);font-weight:700">I FEEL...</div><div class="write-line"></div></div><div><div style="font-size:0.73rem;color:var(--orange);font-weight:700">I NEED...</div><div class="write-line"></div></div><div><div style="font-size:0.73rem;color:var(--orange);font-weight:700">I ASK YOU TO...</div><div class="write-line"></div></div></div></div><div class="section-title">Exercise 2 — Difficult Conversation</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">2</div>The Conversation I Keep Postponing</div><p class="exercise-instruction">Write a conversation you have wanted to have for a long time but keep postponing. With a coach, teammate, or parent.</p><div style="font-size:0.76rem;color:var(--gray-400);margin-bottom:3px">Who is this conversation with?</div><div class="write-line"></div><div style="font-size:0.76rem;color:var(--gray-400);margin:9px 0 3px">Why do I keep postponing it?</div><div class="write-box"></div><div style="font-size:0.76rem;color:var(--gray-400);margin:9px 0 3px">Write the first sentence with which you open the conversation (use the I-Message):</div><div class="write-box"></div><div style="font-size:0.76rem;color:var(--gray-400);margin:9px 0 3px">When will I plan this conversation? (date + place)</div><div class="write-line"></div></div><div class="section-title">Exercise 3 — Feedback Round Reflection</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">3</div>After the Feedback Round</div><p class="exercise-instruction">What was the best feedback you received? What will you concretely do with it?</p><div class="write-box write-box-lg"></div></div>`,
    quote:'"Communication is the most important skill any leader can possess."', cite:'Doc Rivers — NBA Head Coach', footer:'Month 4: Communication', email:'info@characterfirst.be' },
  { m:5, title:'Team First', goalLabel:'Goals Month 5', goals:['You can explain what psychological safety is and why it affects team performance','You actively contribute to a safe team climate by asking for help and acknowledging others','You co-sign a joint team contract that guides the season'], intro:'The step from "I" to "we" is the hardest in sports. Today you explore what it really means to put the team first, even when it costs you something.', badge:'Player', monthLabel:'Month 5 — Player Worksheet',
    exercises:`<div class="section-title">Exercise 1 — Team Contract</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">1</div>My Contribution to the Team Contract</div><p class="exercise-instruction">Write three behavioral rules you personally want to uphold this season — not about winning, but about how you treat your teammates.</p><div class="write-lines" style="gap:9px"><div style="display:flex;align-items:center;gap:7px"><span style="font-size:0.73rem;font-weight:700;color:var(--orange);white-space:nowrap">I promise to</span><div class="write-line" style="flex:1"></div></div><div style="display:flex;align-items:center;gap:7px"><span style="font-size:0.73rem;font-weight:700;color:var(--orange);white-space:nowrap">I promise to</span><div class="write-line" style="flex:1"></div></div><div style="display:flex;align-items:center;gap:7px"><span style="font-size:0.73rem;font-weight:700;color:var(--orange);white-space:nowrap">I promise to</span><div class="write-line" style="flex:1"></div></div></div><div style="margin-top:12px;display:flex;gap:18px"><div style="flex:1"><div style="font-size:0.73rem;color:var(--gray-400);margin-bottom:5px">Signature</div><div class="write-line"></div></div><div style="flex:1"><div style="font-size:0.73rem;color:var(--gray-400);margin-bottom:5px">Date</div><div class="write-line"></div></div></div></div><div class="section-title">Exercise 2 — Invisible Contribution</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">2</div>Invisible Contribution</div><p class="exercise-instruction">Write one teammate who did something during the last match or training that nobody noticed but was essential for the team. What did this person do?</p><div style="font-size:0.76rem;color:var(--gray-400);margin-bottom:3px">Teammate name:</div><div class="write-line"></div><div style="font-size:0.76rem;color:var(--gray-400);margin:9px 0 3px">What did he or she do?</div><div class="write-box write-box-lg"></div></div><div class="section-title">Exercise 3 — Asking for Help</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">3</div>Help Log</div><p class="exercise-instruction">Ask a teammate for help actively at least 3 times this month during training. Write down what you asked and what it produced.</p><div style="display:grid;grid-template-columns:2fr 2fr 1fr;gap:7px;margin-top:7px"><div style="font-size:0.7rem;font-weight:700;color:var(--gray-400)">WHAT DID I ASK?</div><div style="font-size:0.7rem;font-weight:700;color:var(--gray-400)">WHAT DID IT PRODUCE?</div><div style="font-size:0.7rem;font-weight:700;color:var(--gray-400)">DATE</div><div class="write-line"></div><div class="write-line"></div><div class="write-line"></div><div class="write-line"></div><div class="write-line"></div><div class="write-line"></div><div class="write-line"></div><div class="write-line"></div><div class="write-line"></div></div></div>`,
    quote:'"Talent wins games, but teamwork and intelligence win championships."', cite:'Michael Jordan — 6x NBA Champion', footer:'Month 5: Team First', email:'info@characterfirst.be' },
  { m:6, title:'Resilience & Growth Mindset', goalLabel:'Goals Month 6', goals:['You distinguish a fixed mindset reaction from a growth mindset reaction in yourself','You rewrite at least one negative self-thought into a learning-oriented formulation','You name three concrete ways you have grown this season compared to yourself'], intro:'How you deal with setbacks and mistakes determines how far you go in sports and in life. A growth mindset is not innate. You can train it.', badge:'Player', monthLabel:'Month 6 — Player Worksheet',
    exercises:`<div class="section-title">Exercise 1 — Rewrite the Mistake</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">1</div>Rewrite the Mistake</div><p class="exercise-instruction">Write down a recent mistake or setback. Then rewrite every thought with "I can't" to "I can't yet" and add what you learn from it.</p><div style="font-size:0.76rem;color:var(--gray-400);margin-bottom:3px">The situation or mistake:</div><div class="write-box"></div><div class="two-col" style="margin-top:9px"><div><div style="font-size:0.7rem;font-weight:700;color:#c0392b;margin-bottom:4px">WHAT I THOUGHT (fixed)</div><div class="write-box"></div></div><div><div style="font-size:0.7rem;font-weight:700;color:#27ae60;margin-bottom:4px">HOW I REWRITE IT (growth)</div><div class="write-box"></div></div></div></div><div class="section-title">Exercise 2 — Progress List</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">2</div>3 Things I Can Do Better Than Last Month</div><p class="exercise-instruction">No comparison with others. Only with yourself. Write three concrete things.</p><div class="write-lines" style="gap:9px"><div style="display:flex;align-items:center;gap:7px"><div class="exercise-number" style="flex-shrink:0">1</div><div class="write-line" style="flex:1"></div></div><div style="display:flex;align-items:center;gap:7px"><div class="exercise-number" style="flex-shrink:0">2</div><div class="write-line" style="flex:1"></div></div><div style="display:flex;align-items:center;gap:7px"><div class="exercise-number" style="flex-shrink:0">3</div><div class="write-line" style="flex:1"></div></div></div></div><div class="section-title">Exercise 3 — My Hardest Moment</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">3</div>Hardest Moment of This Season</div><p class="exercise-instruction">Describe the hardest moment of this season. What did you do? What did you learn? How did you become stronger?</p><div style="font-size:0.76rem;color:var(--gray-400);margin-bottom:3px">What was the moment?</div><div class="write-box"></div><div style="font-size:0.76rem;color:var(--gray-400);margin:7px 0 3px">What did I learn from it?</div><div class="write-box"></div></div>`,
    quote:'"I have failed over and over again in my life. And that is why I succeed."', cite:'Michael Jordan — 6x NBA Champion', footer:'Month 6: Resilience & Growth Mindset', email:'info@characterfirst.be' },
  { m:7, title:'Leadership from Within', goalLabel:'Goals Month 7', goals:['You recognize informal leadership in yourself and others without looking at official roles','You deliberately take a leadership moment at least once a week in training or a match','You actively invest in the development of a younger or newer teammate'], intro:'Leadership is not about the captain\'s armband. Every player can lead at any moment through behavior, attitude, and words. You too.', badge:'Player', monthLabel:'Month 7 — Player Worksheet',
    exercises:`<div class="section-title">Exercise 1 — Who Do I Follow?</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">1</div>Informal Leaders in Our Team</div><p class="exercise-instruction">Write two teammates you follow, not because they are captain, but because they radiate something. What do they concretely do that has influence?</p><div style="margin-bottom:11px"><div style="font-size:0.73rem;color:var(--gray-400);margin-bottom:3px">Person 1 name:</div><div class="write-line"></div><div style="font-size:0.73rem;color:var(--gray-400);margin:5px 0 3px">What makes him or her influential?</div><div class="write-box"></div></div><div><div style="font-size:0.73rem;color:var(--gray-400);margin-bottom:3px">Person 2 name:</div><div class="write-line"></div><div style="font-size:0.73rem;color:var(--gray-400);margin:5px 0 3px">What makes him or her influential?</div><div class="write-box"></div></div></div><div class="section-title">Exercise 2 — Mentor a Younger Player</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">2</div>My Mentor Moment</div><p class="exercise-instruction">Choose a younger player or new teammate. Spend at least 5 minutes with him or her once this month. Write what you wanted to share and how it went.</p><div style="font-size:0.76rem;color:var(--gray-400);margin-bottom:3px">With whom?</div><div class="write-line"></div><div style="font-size:0.76rem;color:var(--gray-400);margin:7px 0 3px">What did I want to share?</div><div class="write-box"></div><div style="font-size:0.76rem;color:var(--gray-400);margin:7px 0 3px">How did that person respond?</div><div class="write-box"></div></div><div class="section-title">Exercise 3 — The First Voice</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">3</div>My Leadership Moments</div><p class="exercise-instruction">Write after each training or match: when were you the first voice? When did you take a leadership moment?</p><div class="write-box write-box-lg"></div></div>`,
    quote:'"I like pressure. It\'s a privilege to be in pressure situations."', cite:'LeBron James — 4x NBA Champion, Los Angeles Lakers', footer:'Month 7: Leadership from Within', email:'info@characterfirst.be' },
  { m:8, title:'Legacy & Next Step', goalLabel:'Goals Month 8', goals:['You reflect on your growth as a person and teammate over the full season','You formulate three concrete, behavior-oriented intentions for next season','You close the season with a conscious feeling of purpose and contribution to the team'], intro:'This is the last worksheet of the season. You close with reflection on who you have become, what you have contributed, and what step you want to take.', badge:'Player', monthLabel:'Month 8 — Player Worksheet',
    exercises:`<div class="section-title">Exercise 1 — My Contribution This Season</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">1</div>5 Moments of Character</div><p class="exercise-instruction">Write five concrete moments this season when you contributed something that made the team stronger. No statistics, only behavior and character.</p><div class="write-lines" style="gap:7px"><div style="display:flex;align-items:flex-start;gap:7px"><div class="exercise-number" style="flex-shrink:0;margin-top:2px">1</div><div class="write-box" style="flex:1;height:32px"></div></div><div style="display:flex;align-items:flex-start;gap:7px"><div class="exercise-number" style="flex-shrink:0;margin-top:2px">2</div><div class="write-box" style="flex:1;height:32px"></div></div><div style="display:flex;align-items:flex-start;gap:7px"><div class="exercise-number" style="flex-shrink:0;margin-top:2px">3</div><div class="write-box" style="flex:1;height:32px"></div></div><div style="display:flex;align-items:flex-start;gap:7px"><div class="exercise-number" style="flex-shrink:0;margin-top:2px">4</div><div class="write-box" style="flex:1;height:32px"></div></div><div style="display:flex;align-items:flex-start;gap:7px"><div class="exercise-number" style="flex-shrink:0;margin-top:2px">5</div><div class="write-box" style="flex:1;height:32px"></div></div></div></div><div class="section-title">Exercise 2 — Three Intentions for Next Season</div><div class="exercise-block"><div class="exercise-title"><div class="exercise-number">2</div>My Intentions</div><p class="exercise-instruction">Write three concrete intentions for next season. One for yourself, one for the team, one for your coach. Make them specific in behavior.</p><div style="display:flex;flex-direction:column;gap:9px;margin-top:7px"><div><div style="font-size:0.73rem;font-weight:700;color:var(--orange);margin-bottom:4px">FOR MYSELF</div><div class="write-box"></div></div><div><div style="font-size:0.73rem;font-weight:700;color:var(--orange);margin-bottom:4px">FOR THE TEAM</div><div class="write-box"></div></div><div><div style="font-size:0.73rem;font-weight:700;color:var(--orange);margin-bottom:4px">FOR MY COACH</div><div class="write-box"></div></div></div></div><div class="section-title">Letter to Myself</div><div class="exercise-block" style="border:2px dashed var(--orange)"><div class="exercise-title"><div class="exercise-number">3</div>Letter to My Future Self</div><p class="exercise-instruction">Write a letter to yourself next season. What do you hope to have learned? What kind of teammate do you want to be? This letter will be kept and opened at the start of next season.</p><div class="write-box write-box-lg"></div><div style="font-size:0.76rem;color:var(--gray-400);margin-top:7px">Date: _________________ Signature: _________________</div></div>`,
    quote:'"The strength of the team is each individual member. The strength of each member is the team."', cite:'Phil Jackson — 11x NBA Championship coach', footer:'Month 8: Legacy & Next Step', email:'info@characterfirst.be' },
];

// Coach data (imported from gen_coach data inline for NL and EN)
const COACH_NL_DATA = [
  { m:1, title:'Zelfkennis & Identiteit', monthLabel:'Maand 1 — Coachgids',
    science:`<strong>Wetenschappelijke basis — Evidence piramide</strong><p style="margin-top:5px"><span class="evidence-tier tier-1">Systematische Review</span> Ntoumanis et al. (2021) — meta-analyse van 184 studies: autonomie en zelfkennis zijn sterkste voorspellers van sportmotivatie bij jonge atleten. <em>Psychology of Sport &amp; Exercise.</em></p><p style="margin-top:5px"><span class="evidence-tier tier-2">Meta-analyse</span> Zuber &amp; Conzelmann (2014) — 47 studies: intrinsieke motivatie en zelfconcept hangen direct samen met sportprestatie bij jongeren.</p><p style="margin-top:5px"><span class="evidence-tier tier-3">Longitudinale studie</span> Deci &amp; Ryan (1985/2017) — SDT: autonomie, competentie en verbondenheid als universele basisbehoeften in sport.</p>`,
    sectionTitle:'Begeleiding per oefening',
    steps:['<strong>Mijn Drie Woorden:</strong> Geef spelers 3 minuten solo. Daarna in tweetallen elkaars woorden opschrijven zonder overleg. Groepsdiscussie: "Wie was verrast?" Negatieve verrassingen individueel opvolgen.','<strong>Energiegever vs Energieslurper:</strong> Individueel invullen. Bespreek enkel energiegevers in de groep. Energieslurpers individueel of in vertrouwen bespreken.','<strong>Waardenkompas:</strong> Vrijwilligers delen topwaarde. Klassement op het bord. Vraag: "Hoe zien we dit terug in gedrag?" Brug naar volgende maanden.'],
    tips:['<strong>Tip 1:</strong> Vul zelf ook het werkblad in en deel jouw antwoorden. Kwetsbaarheid van de coach verlaagt de drempel.','<strong>Tip 2:</strong> Maak aantekeningen van wat spelers delen. Gebruik dit later in het seizoen om hen te herinneren aan hun eigen waarden.','<strong>Tip 3:</strong> Spelers die weinig schrijven zijn niet ongemotiveerd. Zelfkennis kan confronterend zijn. Ga individueel op in, niet voor de groep.'],
    warning:'Vermijd: "Wie wil zijn woorden delen?" Direct iemand aanwijzen creëert onveiligheid. Bouw vertrouwen op door eerst zelf te delen.',
    timingTitle:'Tijdsindicatie', timing:['Introductie thema en uitleg: 5 minuten','Individueel invullen werkblad: 10 minuten','Groepsbespreking Drie Woorden: 10 minuten','Groepsbespreking Waardenkompas: 10 minuten','Afsluiting: 5 minuten'],
    footer:'Coachgids Maand 1' },
  { m:2, title:'Druk & Stress', monthLabel:'Maand 2 — Coachgids',
    science:`<strong>Wetenschappelijke basis — Evidence piramide</strong><p style="margin-top:5px"><span class="evidence-tier tier-1">Systematische Review</span> Crocker et al. (2015) — 92 studies: flexibele copingstrategieën sterkste samenhang met prestatie en welzijn in jeugdsport.</p><p style="margin-top:5px"><span class="evidence-tier tier-2">RCT</span> Balban et al. (2023) — cyclische ademhaling reduceert stress significant vs. mindfulness. <em>Cell Reports Medicine.</em></p><p style="margin-top:5px"><span class="evidence-tier tier-3">Kwalitatief</span> Hanton et al. (2009) — stressrespons wordt faciliterend of debiliterend op basis van interpretatie, niet intensiteit.</p>`,
    sectionTitle:'Begeleiding per oefening',
    steps:['<strong>Box Breathing:</strong> Samen als groep voor training. Kring, ogen dicht. "In... 2,3,4. Vasthouden... Uit... Wachten..." 4 keer. Daarna: "Wat merk je?"','<strong>Stressdagboek:</strong> Individueel en privé. Expliciet zeggen: "Dit dagboek is voor jou alleen." Na 2 weken: "Wie heeft patronen ontdekt?"','<strong>Worst Case Best Case:</strong> In koppels. Coach stelt één vraag: "Is jouw Worst Case al ooit echt gebeurd?" Relativeren is het doel.'],
    tips:['<strong>Tip 1:</strong> Normaliseer stress actief: "Elke prof voelt dit. Geen zwakte."','<strong>Tip 2:</strong> Gebruik Box Breathing bij time-outs. 30 seconden ademen voor tactiek = betere opname.','<strong>Tip 3:</strong> Spelers die nooit stress tonen: check individueel in. Kan apathie zijn.'],
    warning:'Pas op: "Je moet dit kunnen" vergroot precies de stress die je probeert te reduceren. Gebruik: "Wat heb jij nodig om rustig te blijven?"',
    timingTitle:'Tijdsindicatie', timing:['Box Breathing groepsoefening: 8 minuten','Uitleg stress en copingstijlen: 5 minuten','Individueel invullen: 10 minuten','Worst Case Best Case in koppels: 10 minuten','Groepsreflectie: 7 minuten'],
    footer:'Coachgids Maand 2' },
  { m:3, title:'Mijn Rol in het Team', monthLabel:'Maand 3 — Coachgids',
    science:`<strong>Wetenschappelijke basis — Evidence piramide</strong><p style="margin-top:5px"><span class="evidence-tier tier-1">Systematische Review</span> Bruner et al. (2021) — rolhelderheid sterkste voorspeller cohesie in jeugdteams, d=0.62. <em>Journal of Sport Sciences.</em></p><p style="margin-top:5px"><span class="evidence-tier tier-2">Longitudinaal</span> Eys et al. (2015) — rolambiguïteit negatief gelinkt aan zelfvertrouwen bij 248 basketbalspelers.</p><p style="margin-top:5px"><span class="evidence-tier tier-3">Theoretisch</span> Carron &amp; Eys (2012) — atleten die actief in hun rol investeren presteren significant beter.</p>`,
    sectionTitle:'Begeleiding Rolcirkel (groepsoefening)',
    steps:['In een cirkel staan. Uitleggen: "Wat draag jij als persoon bij?" (niet technisch).','Elke speler: "Mijn bijdrage is..." Begin zelf als coach.','Na elke speler: één teamgenoot vult aan wat hij/zij ook ziet. Enkel positief.','Afsluiting: "Iedereen heeft een rol. De vraag is: vul jij jouw rol zo goed mogelijk in?"'],
    tips:['<strong>Tip 1:</strong> Rolcompass scores zijn geen ranglijst. Stabiele Kracht is even waardevol als Leider.','<strong>Tip 2:</strong> Gebruik rollen in dagelijkse coaching taal. "Tom, jij bent onze Motor vandaag."','<strong>Tip 3:</strong> Herhaal "Top 3 Bijdragen" maandelijks. Spelers die groei zien presteren beter.'],
    warning:'Spelers die zichzelf laag scoren op alle rollen: plan een individueel gesprek.',
    timingTitle:'Tijdsindicatie', timing:['Introductie vier rollen: 5 minuten','Rolcompass individueel invullen: 8 minuten','Rolcirkel groepsoefening: 15 minuten','Reflectie en werkblad: 5 minuten','Afsluiting: 5 minuten'],
    footer:'Coachgids Maand 3' },
  { m:4, title:'Communicatie', monthLabel:'Maand 4 — Coachgids',
    science:`<strong>Wetenschappelijke basis — Evidence piramide</strong><p style="margin-top:5px"><span class="evidence-tier tier-1">Systematische Review</span> Tod et al. (2011) — communicatietraining in sportteams verbetert cohesie en prestatie.</p><p style="margin-top:5px"><span class="evidence-tier tier-2">RCT</span> Holt et al. (2020) — 8 weken NVC: significant hogere sociale cohesie en minder conflicten. <em>Psychology of Sport &amp; Exercise.</em></p><p style="margin-top:5px"><span class="evidence-tier tier-3">Observationeel</span> Turnnidge &amp; Côté (2018) — positieve communicatie correleert met sportplezier en motivatie bij jonge atleten.</p>`,
    sectionTitle:'Begeleiding Feedbackronde Trio',
    steps:['Groepen van drie. Rol A: gever, Rol B: ontvanger, Rol C: observator (let op toon en woordkeuze, niet inhoud).','Na elke ronde (3 min): observator geeft 30 sec terug: "Je zei... Dat klonk als..." Geen oordeel. Dan rollen wisselen.','Afsluiting: "Wat was moeilijkst aan geven? Aan ontvangen?" Antwoorden leiden groepsgesprek.'],
    tips:['<strong>Tip 1:</strong> Gebruik zelf de Ik Boodschap. Stop met "Jij deed dat fout." Begin met "Ik zie..."','<strong>Tip 2:</strong> Laat spelers een datum plannen voor het moeilijke gesprek. Accountability is essentieel.','<strong>Tip 3:</strong> U14-U16: empathie is in ontwikkeling. Eén bewuste ik-boodschap per maand is al een succes.'],
    warning:'Feedbackronde kan intens worden bij onderlinge spanning. Scan groepsdynamiek. Start met sterke punten bij gespannen sfeer.',
    timingTitle:'Tijdsindicatie', timing:['Uitleg Ik Boodschap: 8 minuten','Individueel oefenen: 8 minuten','Feedbackronde Trio: 15 minuten','Nabespreking: 7 minuten','Intentie gesprek plannen: 2 minuten'],
    footer:'Coachgids Maand 4' },
  { m:5, title:'Team Eerst', monthLabel:'Maand 5 — Coachgids',
    science:`<strong>Wetenschappelijke basis — Evidence piramide</strong><p style="margin-top:5px"><span class="evidence-tier tier-1">Meta-analyse</span> Frazier et al. (2017) — 136 steekproeven: hoge psychologische veiligheid = significant betere creativiteit en leergedrag. <em>Personnel Psychology.</em></p><p style="margin-top:5px"><span class="evidence-tier tier-2">Longitudinaal</span> Fransen et al. (2015) — 23 basketbalteams: sterke "wij" cultuur = hogere prestatiestabiliteit en lagere uitval.</p><p style="margin-top:5px"><span class="evidence-tier tier-3">Kwalitatief</span> Edmondson (1999) — teams die hulp durven vragen leren sneller en presteren beter op lange termijn.</p>`,
    sectionTitle:'Begeleiding Team Contract',
    steps:['Individueel 3 persoonlijke beloftes. Daarna groepen van drie: welke overlappen? Eén belofte per groep voorstellen.','Team stemt over 5 gedragsregels. Iedereen tekent. Ophangen in kleedkamer of digitaal sturen.','Revisie na 4 weken: "Leven we ons contract na?" Maak dit een vast ritueel.'],
    tips:['<strong>Tip 1:</strong> Onzichtbare Bijdrage: lees aantekeningen voor in de groep einde maand. Dit verandert hoe spelers elkaar zien.','<strong>Tip 2:</strong> Beloon "team eerst" gedrag publiekelijk met erkenning, niet punten.','<strong>Tip 3:</strong> Noem eigen fouten als coach. Dit geeft spelers toestemming om kwetsbaar te zijn.'],
    warning:'Competitieve spelers met weinig speeltijd kunnen dit thema zwaar vinden. Individueel gesprek, geen groepsdiscussie.',
    timingTitle:'Tijdsindicatie', timing:['Uitleg psychologische veiligheid: 5 minuten','Individueel Team Contract: 5 minuten','Groepsproces contract: 15 minuten','Ondertekening: 5 minuten','Uitleg Onzichtbare Bijdrage: 5 minuten'],
    footer:'Coachgids Maand 5' },
  { m:6, title:'Veerkracht & Groeimindset', monthLabel:'Maand 6 — Coachgids',
    science:`<strong>Wetenschappelijke basis — Evidence piramide</strong><p style="margin-top:5px"><span class="evidence-tier tier-1">Meta-analyse</span> Burnette et al. (2013) — 113 studies: groeimindset correleert met leergerichte doelen en betere prestaties bij adolescenten. <em>Psychological Bulletin.</em></p><p style="margin-top:5px"><span class="evidence-tier tier-2">Systematische Review</span> Meijen et al. (2020) — cognitieve herframing is meest evidence-based strategie voor veerkracht in sport. <em>Frontiers in Psychology.</em></p><p style="margin-top:5px"><span class="evidence-tier tier-3">Longitudinaal</span> Martin &amp; Marsh (2009) — veerkracht is betere voorspeller van langetermijnsucces dan IQ of motivatie.</p>`,
    sectionTitle:'Begeleiding Herschrijf de Fout',
    steps:['Introduceer fixed vs. growth mindset met echt eigen voorbeeld: "Ik dacht dat ik niet snel genoeg was..."','Individueel schrijven. Privé mag blijven. Daarna: wie deelt de "herschreven" versie? Focus op learning, niet op de fout.'],
    tips:['<strong>Tip 1:</strong> Verander eigen taal. Stop "Dat is niks voor jou." Begin "Dat heb je nog niet onder de knie."','<strong>Tip 2:</strong> Progressielijst als vast ritueel elke sessie. Stabielere spelers met minder externe bevestiging nodig.','<strong>Tip 3:</strong> Maand 6 = vermoeidheid en motivatiedip. Dit thema is bewust als heroriëntatie geplaatst.'],
    warning:'Groeimindset kan averechts werken als camouflage voor gebrek aan steun. Combineer met concrete handvatten en individuele begeleiding.',
    timingTitle:'Tijdsindicatie', timing:['Introductie fixed vs. growth mindset: 8 minuten','Individueel invullen: 10 minuten','Groepsreflectie herschreven fouten: 10 minuten','Progressielijst en afsluiting: 7 minuten'],
    footer:'Coachgids Maand 6' },
  { m:7, title:'Leiderschap van Binnenuit', monthLabel:'Maand 7 — Coachgids',
    science:`<strong>Wetenschappelijke basis — Evidence piramide</strong><p style="margin-top:5px"><span class="evidence-tier tier-1">Systematische Review</span> Cotterill &amp; Fransen (2016) — gedeeld leiderschap correleert sterker met cohesie en prestatie dan enkelvoudig formeel leiderschap. <em>Psychology of Sport &amp; Exercise.</em></p><p style="margin-top:5px"><span class="evidence-tier tier-2">Multi-seizoen</span> Fransen et al. (2020) — teams met 3+ informele leiders presteren stabieler dan teams met 1 formele leider. <em>Journal of Sport Sciences.</em></p><p style="margin-top:5px"><span class="evidence-tier tier-3">Theoretisch</span> Côté &amp; Gilbert (2009) — servant leadership verhoogt teamvertrouwen significant.</p>`,
    sectionTitle:'Begeleiding "De Eerste Stem"',
    steps:['"De Eerste Stem": eerste constructieve stem na time-out, tegengoal of voor training. Leiderschap in actie.','Speler aanwijzen als "leider van de dag". Roteert. Opent warming-up, pre-game speech of afkoeling.','Na sessie evalueren met leider van de dag: "Hoe voelde het? Wat ga je volgende keer anders doen?"'],
    tips:['<strong>Tip 1:</strong> Verbreed het begrip leider. Altijd op tijd, klaar voor een teamgenoot, nooit opgeven = ook leiderschap.','<strong>Tip 2:</strong> Koppel ervaren speler aan nieuwere speler. Gezamenlijke kleine taak geven.','<strong>Tip 3:</strong> Geef leidersgedrag een naam als je het ziet. "Dat was leiderschap."'],
    warning:'Leiderschap is niet altijd luid en zichtbaar. Benoem actief dat luisteren en consistent zijn ook leiderschapsgedrag zijn.',
    timingTitle:'Tijdsindicatie', timing:['Introductie gedeeld leiderschap: 5 minuten','Groepsbespreking informele leiders: 10 minuten','Leider van de Dag plannen: 10 minuten','Mentormoment invullen: 2 minuten','Afsluiting: 3 minuten'],
    footer:'Coachgids Maand 7' },
  { m:8, title:'Nalatenschap & Volgende Stap', monthLabel:'Maand 8 — Coachgids',
    science:`<strong>Wetenschappelijke basis — Evidence piramide</strong><p style="margin-top:5px"><span class="evidence-tier tier-1">Systematische Review</span> Henriksen et al. (2020) — 44 studies: seizoensafsluitingen met reflectie op waarden verhogen identiteitsontwikkeling en langetermijnparticipatie. <em>British Journal of Sports Medicine.</em></p><p style="margin-top:5px"><span class="evidence-tier tier-2">Longitudinaal</span> Seizoensreflectie = hogere intrinsieke motivatie volgend seizoen.</p><p style="margin-top:5px"><span class="evidence-tier tier-3">Theoretisch</span> Seligman (2011) — PERMA: meaning en accomplishment zijn meest onderschatte welzijnscomponenten bij adolescenten.</p>`,
    sectionTitle:'De Slotsessie begeleiden',
    steps:['Terugblik met werkblad Maand 1 (Drie Woorden). Vergelijken: "Ben je gegroeid?" Krachtig gevoel van progressie.','Onzichtbare Bijdragen voorlezen uit maand 5. Met naam, na toestemming. Emotioneel hoogtepunt.','Brieven verzegelen. Jij bewaart als coach, geeft terug bij start volgend seizoen. Grote symbolische waarde.','Slotceremonie: elke speler zegt één ding geleerd over zichzelf. Niet over basketbal. Over karakter.'],
    tips:['<strong>Tip 1:</strong> Schrijf zelf ook een brief als coach. Deel een stuk: "Wat hoop ik beter te doen?" Sluit af in geest waarmee het begon.','<strong>Tip 2:</strong> Stuur elk speler een persoonlijk berichtje over één moment van karakter dat jij hebt gezien.','<strong>Tip 3:</strong> Gebruik Maand 8 intenties bij start volgend seizoen: "Je schreef dat je de eerste stem wilde zijn. Hoe is dat gegaan?"'],
    warning:'Slotsessie minimum 45 minuten. Dit is het hoogtepunt van 8 maanden werk. Geef het de ruimte die het verdient.',
    timingTitle:'Tijdsindicatie Slotsessie', timing:['Terugblik Maand 1 werkbladen: 10 minuten','Voorlezen Onzichtbare Bijdragen: 10 minuten','Werkblad Maand 8 invullen: 15 minuten','Brieven verzegelen: 5 minuten','Slotceremonie: 10 minuten','Afsluitende woorden coach: 5 minuten'],
    footer:'Coachgids Maand 8' },
];

const COACH_EN_DATA = [
  { m:1, title:'Self-Knowledge & Identity', monthLabel:'Month 1 — Coach Guide',
    science:`<strong>Scientific Foundation — Evidence Pyramid</strong><p style="margin-top:5px"><span class="evidence-tier tier-1">Systematic Review</span> Ntoumanis et al. (2021) — 184 studies: autonomy and self-knowledge are strongest predictors of sports motivation in young athletes. <em>Psychology of Sport &amp; Exercise.</em></p><p style="margin-top:5px"><span class="evidence-tier tier-2">Meta-analysis</span> Zuber &amp; Conzelmann (2014) — 47 studies: intrinsic motivation and self-concept directly linked to youth sports performance.</p><p style="margin-top:5px"><span class="evidence-tier tier-3">Longitudinal</span> Deci &amp; Ryan (1985/2017) — SDT: autonomy, competence, and relatedness as universal basic needs in sport.</p>`,
    sectionTitle:'Guidance per exercise',
    steps:['<strong>My Three Words:</strong> 3 minutes solo writing. Then pairs write each other\'s words without consulting. Group discussion: "Who was surprised?" Handle negative surprises individually.','<strong>Energy Givers vs Drains:</strong> Fill in individually. Discuss only energy givers in the group. Discuss drains individually or confidentially.','<strong>Values Compass:</strong> Volunteers share top value. Ranking on board. Ask: "How do we see this in behavior?" Bridge to coming months.'],
    tips:['<strong>Tip 1:</strong> Fill in the worksheet yourself and share your answers. Vulnerability from the coach lowers the threshold.','<strong>Tip 2:</strong> Take notes of what players share. Use this later to remind them of their own values.','<strong>Tip 3:</strong> Players who write little are not unmotivated. Self-knowledge can be confronting. Address individually, not in front of the group.'],
    warning:'Avoid: "Who wants to share their words?" Pointing someone out creates insecurity. Build trust by sharing first yourself.',
    timingTitle:'Timing', timing:['Introduction and explanation: 5 minutes','Individual worksheet completion: 10 minutes','Group discussion Three Words: 10 minutes','Group discussion Values Compass: 10 minutes','Closing: 5 minutes'],
    footer:'Coach Guide Month 1' },
  { m:2, title:'Pressure & Stress', monthLabel:'Month 2 — Coach Guide',
    science:`<strong>Scientific Foundation — Evidence Pyramid</strong><p style="margin-top:5px"><span class="evidence-tier tier-1">Systematic Review</span> Crocker et al. (2015) — 92 studies: flexible coping strategies show strongest link to performance and well-being in youth sport.</p><p style="margin-top:5px"><span class="evidence-tier tier-2">RCT</span> Balban et al. (2023) — cyclic breathing significantly reduces stress vs. mindfulness. <em>Cell Reports Medicine.</em></p><p style="margin-top:5px"><span class="evidence-tier tier-3">Qualitative</span> Hanton et al. (2009) — stress response becomes facilitating or debilitating based on interpretation, not intensity.</p>`,
    sectionTitle:'Guidance per exercise',
    steps:['<strong>Box Breathing:</strong> Together as group before training. Circle, eyes closed. "In... 2,3,4. Hold... Out... Wait..." 4 times. Then: "What do you notice?"','<strong>Stress Diary:</strong> Individual and private. Say explicitly: "This diary is for you alone." After 2 weeks: "Who noticed patterns?"','<strong>Worst Case Best Case:</strong> In pairs. Coach asks one question: "Has your Worst Case ever actually happened?" Relativizing is the goal.'],
    tips:['<strong>Tip 1:</strong> Actively normalize stress: "Every pro feels this. Not a weakness."','<strong>Tip 2:</strong> Use Box Breathing at time-outs. 30 seconds breathing before tactics = better information retention.','<strong>Tip 3:</strong> Players who never show stress: check in individually. May be apathy.'],
    warning:'Beware: "You should be able to handle this" amplifies exactly the stress you\'re trying to reduce. Use: "What do you need to stay calm?"',
    timingTitle:'Timing', timing:['Group Box Breathing: 8 minutes','Explanation of stress and coping: 5 minutes','Individual worksheet: 10 minutes','Worst Case Best Case in pairs: 10 minutes','Group reflection: 7 minutes'],
    footer:'Coach Guide Month 2' },
  { m:3, title:'My Role in the Team', monthLabel:'Month 3 — Coach Guide',
    science:`<strong>Scientific Foundation — Evidence Pyramid</strong><p style="margin-top:5px"><span class="evidence-tier tier-1">Systematic Review</span> Bruner et al. (2021) — role clarity is strongest predictor of cohesion in youth teams, d=0.62. <em>Journal of Sport Sciences.</em></p><p style="margin-top:5px"><span class="evidence-tier tier-2">Longitudinal</span> Eys et al. (2015) — role ambiguity negatively linked to self-confidence in 248 basketball players.</p><p style="margin-top:5px"><span class="evidence-tier tier-3">Theoretical</span> Carron &amp; Eys (2012) — athletes who actively invest in their role perform significantly better.</p>`,
    sectionTitle:'Guidance Role Circle (group exercise)',
    steps:['Stand in a circle. Explain: "Name your personal contribution to this team" (not technical).','Each player: "My contribution is..." Start yourself as coach.','After each player: one teammate adds what they also see. Positive only. No irony, no "yes but".','Close: "Everyone has a role. No one is unimportant. Are you fulfilling your role as well as possible?"'],
    tips:['<strong>Tip 1:</strong> Role Compass scores are not a ranking. A Stable Force is just as valuable as a Leader.','<strong>Tip 2:</strong> Use roles in daily coaching language. "Tom, you\'re our Engine today."','<strong>Tip 3:</strong> Repeat "Top 3 Contributions" monthly. Players who see growth perform better and drop out less.'],
    warning:'Players who score low on all roles may feel they don\'t fit or aren\'t seen. Schedule an individual conversation.',
    timingTitle:'Timing', timing:['Introduction of four roles: 5 minutes','Role Compass individual: 8 minutes','Role Circle group exercise: 15 minutes','Reflection and worksheet: 5 minutes','Closing: 5 minutes'],
    footer:'Coach Guide Month 3' },
  { m:4, title:'Communication', monthLabel:'Month 4 — Coach Guide',
    science:`<strong>Scientific Foundation — Evidence Pyramid</strong><p style="margin-top:5px"><span class="evidence-tier tier-1">Systematic Review</span> Tod et al. (2011) — communication training in sports teams improves cohesion and performance.</p><p style="margin-top:5px"><span class="evidence-tier tier-2">RCT</span> Holt et al. (2020) — 8 weeks NVC: significantly higher social cohesion and fewer conflicts. <em>Psychology of Sport &amp; Exercise.</em></p><p style="margin-top:5px"><span class="evidence-tier tier-3">Observational</span> Turnnidge &amp; Côté (2018) — positive communication correlates with enjoyment and motivation in young athletes.</p>`,
    sectionTitle:'Guidance Feedback Trio Round',
    steps:['Groups of three. Role A: giver, Role B: receiver, Role C: observer (tone and word choice only, not content).','After each round (3 min): observer gives 30 sec: "You said... That sounded like..." No judgment. Then switch roles.','Close: "What was hardest about giving? About receiving?" Answers lead group conversation.'],
    tips:['<strong>Tip 1:</strong> Use the I-Message yourself. Stop "You did that wrong." Start "I see..."','<strong>Tip 2:</strong> Have players plan a date for the difficult conversation. Accountability is essential.','<strong>Tip 3:</strong> U14-U16: empathy is developing. One conscious I-message per month is already a success.'],
    warning:'Feedback round can get intense with group tension. Scan dynamics first. Start with strengths in a tense atmosphere.',
    timingTitle:'Timing', timing:['I-Message explanation: 8 minutes','Individual practice: 8 minutes','Feedback Trio Round: 15 minutes','Debrief: 7 minutes','Planning difficult conversation: 2 minutes'],
    footer:'Coach Guide Month 4' },
  { m:5, title:'Team First', monthLabel:'Month 5 — Coach Guide',
    science:`<strong>Scientific Foundation — Evidence Pyramid</strong><p style="margin-top:5px"><span class="evidence-tier tier-1">Meta-analysis</span> Frazier et al. (2017) — 136 samples: high psychological safety = significantly better creativity and learning behavior. <em>Personnel Psychology.</em></p><p style="margin-top:5px"><span class="evidence-tier tier-2">Longitudinal</span> Fransen et al. (2015) — 23 basketball teams: strong "we" culture = higher performance stability and lower dropout.</p><p style="margin-top:5px"><span class="evidence-tier tier-3">Qualitative</span> Edmondson (1999) — teams that dare to ask for help learn faster and perform better long-term.</p>`,
    sectionTitle:'Guidance Team Contract',
    steps:['Individually write 3 personal promises. Then groups of three: which overlap? Each group proposes one promise.','Team votes on 5 behavioral rules. Everyone signs. Post in locker room or send digitally.','Review after 4 weeks: "Are we honoring our contract?" Make this a fixed ritual.'],
    tips:['<strong>Tip 1:</strong> Invisible Contribution: read notes aloud at end of month. This changes how players see each other.','<strong>Tip 2:</strong> Publicly reward "team first" behavior with recognition, not points.','<strong>Tip 3:</strong> Name your own mistakes as coach. This gives players permission to be vulnerable.'],
    warning:'Competitive players with little playing time may struggle with "team first." Use it for an individual conversation, not a group discussion.',
    timingTitle:'Timing', timing:['Explanation psychological safety: 5 minutes','Individual Team Contract: 5 minutes','Group process toward contract: 15 minutes','Signing and closing: 5 minutes','Invisible Contribution explanation: 5 minutes'],
    footer:'Coach Guide Month 5' },
  { m:6, title:'Resilience & Growth Mindset', monthLabel:'Month 6 — Coach Guide',
    science:`<strong>Scientific Foundation — Evidence Pyramid</strong><p style="margin-top:5px"><span class="evidence-tier tier-1">Meta-analysis</span> Burnette et al. (2013) — 113 studies: growth mindset correlates with learning goals and better performance in adolescents. <em>Psychological Bulletin.</em></p><p style="margin-top:5px"><span class="evidence-tier tier-2">Systematic Review</span> Meijen et al. (2020) — cognitive reframing is most evidence-based strategy for resilience in sport. <em>Frontiers in Psychology.</em></p><p style="margin-top:5px"><span class="evidence-tier tier-3">Longitudinal</span> Martin &amp; Marsh (2009) — resilience is a better predictor of long-term success than IQ or motivation.</p>`,
    sectionTitle:'Guidance Rewrite the Mistake',
    steps:['Introduce fixed vs. growth mindset with real personal example: "I always thought I wasn\'t fast enough..."','Individual writing. May stay private. Then: who shares the "rewritten" version? Focus on learning, not the mistake.'],
    tips:['<strong>Tip 1:</strong> Change your own language. Stop "That\'s not for you." Start "You haven\'t mastered that yet."','<strong>Tip 2:</strong> Progress List as fixed ritual every session. Players who see improvement need less external validation.','<strong>Tip 3:</strong> Month 6 = fatigue and motivation dip. This theme is deliberately placed here as reorientation.'],
    warning:'Growth mindset can backfire as camouflage for lack of support. Always combine with concrete tools and individual guidance.',
    timingTitle:'Timing', timing:['Introduction fixed vs. growth mindset: 8 minutes','Individual worksheet: 10 minutes','Group reflection on rewritten mistakes: 10 minutes','Progress list and closing: 7 minutes'],
    footer:'Coach Guide Month 6' },
  { m:7, title:'Leadership from Within', monthLabel:'Month 7 — Coach Guide',
    science:`<strong>Scientific Foundation — Evidence Pyramid</strong><p style="margin-top:5px"><span class="evidence-tier tier-1">Systematic Review</span> Cotterill &amp; Fransen (2016) — shared leadership correlates more strongly with cohesion and performance than single formal leadership. <em>Psychology of Sport &amp; Exercise.</em></p><p style="margin-top:5px"><span class="evidence-tier tier-2">Multi-season</span> Fransen et al. (2020) — teams with 3+ informal leaders perform more consistently than teams with 1 formal leader. <em>Journal of Sport Sciences.</em></p><p style="margin-top:5px"><span class="evidence-tier tier-3">Theoretical</span> Côté &amp; Gilbert (2009) — servant leadership significantly increases team trust.</p>`,
    sectionTitle:'Guidance "The First Voice"',
    steps:['"The First Voice": first constructive voice after a time-out, setback, or before training. Leadership in action.','Designate a player as "leader of the day." Rotate. Opens warm-up, pre-game speech, or cool-down.','Evaluate with leader of the day after session: "How did it feel? What will you do differently next time?"'],
    tips:['<strong>Tip 1:</strong> Broaden the concept of leader. Always on time, ready for a teammate, never give up = also leadership.','<strong>Tip 2:</strong> Pair experienced player with newer player. Give them a small shared task.','<strong>Tip 3:</strong> Name leadership behavior when you see it. "That was leadership."'],
    warning:'Leadership is not always loud and visible. Actively name listening and consistency as leadership behaviors too.',
    timingTitle:'Timing', timing:['Introduction shared leadership: 5 minutes','Group discussion informal leaders: 10 minutes','Planning Leader of the Day: 10 minutes','Mentor moment completion: 2 minutes','Closing: 3 minutes'],
    footer:'Coach Guide Month 7' },
  { m:8, title:'Legacy & Next Step', monthLabel:'Month 8 — Coach Guide',
    science:`<strong>Scientific Foundation — Evidence Pyramid</strong><p style="margin-top:5px"><span class="evidence-tier tier-1">Systematic Review</span> Henriksen et al. (2020) — 44 studies: end-of-season reflection on values significantly increases identity development and long-term sport participation. <em>British Journal of Sports Medicine.</em></p><p style="margin-top:5px"><span class="evidence-tier tier-2">Longitudinal</span> End-of-season reflection = higher intrinsic motivation the following season.</p><p style="margin-top:5px"><span class="evidence-tier tier-3">Theoretical</span> Seligman (2011) — PERMA: meaning and accomplishment are most underestimated well-being components in adolescents.</p>`,
    sectionTitle:'Guiding the Closing Session',
    steps:['Look back with Month 1 worksheet (Three Words). Compare: "Have you grown?" Creates powerful sense of progression.','Read Invisible Contributions from month 5. By name, with permission. Emotional highlight of the program.','Letters sealed. You keep as coach, return at start of next season. Great symbolic value.','Closing ceremony: each player names one thing learned about themselves. Not about basketball. About character.'],
    tips:['<strong>Tip 1:</strong> Write your own letter as coach. Share part: "What do I hope to do better?" Closes the program as it began.','<strong>Tip 2:</strong> Send each player a personal message about one moment of character you witnessed.','<strong>Tip 3:</strong> Use Month 8 intentions at start of next season: "You wrote you wanted to be the first voice more. How did that go?"'],
    warning:'Closing session needs minimum 45 minutes. This is the highlight of 8 months of work. Give it the space it deserves.',
    timingTitle:'Closing Session Timing', timing:['Look back at Month 1: 10 minutes','Reading Invisible Contributions: 10 minutes','Month 8 worksheet completion: 15 minutes','Letters sealed: 5 minutes','Closing ceremony: 10 minutes','Coach closing words: 5 minutes'],
    footer:'Coach Guide Month 8' },
];

function buildPlayerPage(p, isEN) {
  const goals = p.goals.map(g => `<li>${g}</li>`).join('');
  return `<div class="page">
  <div class="page-header">
    <div class="page-header-left"><div class="month-label">${p.monthLabel}</div><h2>${p.title}</h2></div>
    <div class="page-header-right"><span class="page-type-badge badge-player">${p.badge}</span><div class="logo-small">Character <span>First</span></div></div>
  </div>
  <div class="goal-box"><div class="goal-label">${p.goalLabel}</div><ul>${goals}</ul></div>
  <div class="intro-box">${p.intro}</div>
  ${p.exercises}
  <div class="quote-block"><p>${p.quote}</p><cite>${p.cite}</cite></div>
  <div class="page-footer"><span>Character First — ${p.footer}</span><span>${p.email}</span></div>
</div>`;
}

function buildCoachPage(c, isEN) {
  const steps = c.steps.map((s,i) => `<div class="coach-step"><div class="step-num">${i+1}</div><p>${s}</p></div>`).join('\n');
  const tips = c.tips.map(t => `<div class="tip-box"><p>${t}</p></div>`).join('\n');
  const timing = c.timing.map(t => `<li><div class="checkbox"></div>${t}</li>`).join('\n');
  const confLabel = isEN ? 'CONFIDENTIAL — Coaches only' : 'VERTROUWELIJK — Enkel voor coaches';
  return `<div class="page coach-page" style="page-break-after:auto;break-after:auto">
  <div class="page-header">
    <div class="page-header-left"><div class="month-label">${c.monthLabel}</div><h2>${c.title}</h2></div>
    <div class="page-header-right"><span class="page-type-badge badge-coach">Coach</span><div class="logo-small">Character <span>First</span></div></div>
  </div>
  <div class="science-box">${c.science}</div>
  <div class="coach-section"><h3>${c.sectionTitle}</h3>${steps}</div>
  <div class="coach-section"><h3>${isEN ? 'Coach tips for this theme' : 'Coach tips voor dit thema'}</h3>${tips}<div class="warning-box"><p>&#9888; ${c.warning}</p></div></div>
  <div class="coach-section"><h3>${c.timingTitle}</h3><ul class="checklist">${timing}</ul></div>
  <div class="page-footer"><span>Character First — ${c.footer}</span><span>${confLabel}</span></div>
</div>`;
}

function buildVolledigHTML(playerData, coachData, isEN) {
  const player = buildPlayerPage(playerData, isEN);
  const coach = buildCoachPage(coachData, isEN);
  const lang = isEN ? 'en' : 'nl';
  return `<!DOCTYPE html>
<html lang="${lang}">
<head><meta charset="UTF-8"/><style>${PCSS}</style></head>
<body>${player}${coach}</body>
</html>`;
}

(async () => {
  const browser = await chromium.launch();

  // Volledig NL
  for (let i = 0; i < 8; i++) {
    const m = i + 1;
    const html = buildVolledigHTML(PLAYER_NL[i], COACH_NL_DATA[i], false);
    const tmp = `/tmp/volledig_m${m}_nl.html`;
    fs.writeFileSync(tmp, html);
    const page = await browser.newPage();
    await page.goto('file://' + tmp, { waitUntil: 'networkidle' });
    await page.waitForTimeout(400);
    const out = path.join(DIRS.volledigNL, `CF_Werkblad_M${m}_NL.pdf`);
    await page.pdf({ path: out, format: 'A4', printBackground: true, margin: { top: '8mm', bottom: '8mm', left: '8mm', right: '8mm' } });
    await page.close();
    fs.unlinkSync(tmp);
    console.log(`Volledig NL M${m} → ${Math.round(fs.statSync(out).size/1024)}KB`);
  }

  // Volledig EN
  for (let i = 0; i < 8; i++) {
    const m = i + 1;
    const html = buildVolledigHTML(PLAYER_EN[i], COACH_EN_DATA[i], true);
    const tmp = `/tmp/volledig_m${m}_en.html`;
    fs.writeFileSync(tmp, html);
    const page = await browser.newPage();
    await page.goto('file://' + tmp, { waitUntil: 'networkidle' });
    await page.waitForTimeout(400);
    const out = path.join(DIRS.volledigEN, `CF_Werkblad_M${m}_EN.pdf`);
    await page.pdf({ path: out, format: 'A4', printBackground: true, margin: { top: '8mm', bottom: '8mm', left: '8mm', right: '8mm' } });
    await page.close();
    fs.unlinkSync(tmp);
    console.log(`Volledig EN M${m} → ${Math.round(fs.statSync(out).size/1024)}KB`);
  }

  await browser.close();
  console.log('Done!');
})();
